public class CountingAdvice {
    @Advice.OnMethodEnter                                  // copied to the start of the method
    static void enter(@Advice.Origin("#t.#m") String method) {
        CallCounts.hit(method);                            // must be public: this code runs in the target class
    }
}

// install it
new AgentBuilder.Default()
        .disableClassFormatChanges()
        .with(AgentBuilder.RedefinitionStrategy.RETRANSFORMATION)
        .type(is(SettlementJob.class))
        .transform((b, type, loader, module, domain) -> b.visit(Advice.to(CountingAdvice.class).on(named("settle"))))
        .installOn(ByteBuddyAgent.install());

