public static void agentmain(String args, Instrumentation inst) throws Exception {
    LoggingTransformer t = new LoggingTransformer("com/acme/IssuerClient");
    inst.addTransformer(t, true);                               // 1. canRetransform = true
    for (Class<?> c : inst.getAllLoadedClasses()) {
        if (c.getName().equals("com.acme.IssuerClient")) {
            inst.retransformClasses(c);                         // 2. run the transformers again for it
        }
    }
}

